from pathlib import Path
p=Path('world/looks/crystal_common.gdshaderinc');s=p.read_text();i=s.index('// The hackle ripple')
s=s[:i]+'''// Two dominant projections, with explicit gradients across the axis-selection seams.
float crystal_comp(vec3 p, int a) {
	return a == 0 ? p.x : (a == 1 ? p.y : p.z);
}
vec2 crystal_plane(vec3 p, int a) {
	return a == 0 ? p.yz : (a == 1 ? p.zx : p.xy);
}
vec3 crystal_axis(int a) {
	return vec3(a == 0 ? 1.0 : 0.0, a == 1 ? 1.0 : 0.0, a == 2 ? 1.0 : 0.0);
}
void crystal_axes(vec3 nt, out int a, out int b, out float w) {
	vec3 n = abs(nt);
	a = n.x >= n.y ? (n.x >= n.z ? 0 : 2) : (n.y >= n.z ? 1 : 2);
	int c = n.x <= n.y ? (n.x <= n.z ? 0 : 2) : (n.y <= n.z ? 1 : 2);
	if (a == c) { c = (a + 2) % 3; }
	b = 3 - a - c;
	float wa = pow(crystal_comp(n, a), 4.0);
	float wb = pow(crystal_comp(n, b), 4.0);
	w = wa / max(wa + wb, 1e-12);
}
vec2 crystal_mask(vec3 tp, vec3 nt) {
	int a;
	int b;
	float w;
	crystal_axes(nt, a, b, w);
	vec3 p = tp * mask_scale;
	vec3 dx = dFdx(p);
	vec3 dy = dFdy(p);
	return mix(textureGrad(mask_tex, crystal_plane(p, b), crystal_plane(dx, b), crystal_plane(dy, b)).rg,
		textureGrad(mask_tex, crystal_plane(p, a), crystal_plane(dx, a), crystal_plane(dy, a)).rg, w);
}
// Rigid derivative frame: carries vectors in either direction without a per-stone matrix.
vec3 crystal_to_view(vec3 d, vec3 nv, vec3 nt, vec3 vtx, vec3 tp) {
	vec3 tt = normalize(dFdx(tp));
	vec3 tv = normalize(dFdx(vtx));
	return normalize(tv * dot(tt, d) + cross(nv, tv) * dot(cross(nt, tt), d) + nv * dot(nt, d));
}
vec3 crystal_view_pattern(vec3 v, vec3 nv, vec3 nt, vec3 vtx, vec3 tp) {
	vec3 tt = normalize(dFdx(tp));
	vec3 tv = normalize(dFdx(vtx));
	return tt * dot(tv, v) + cross(nt, tt) * dot(cross(nv, tv), v) + nt * dot(nv, v);
}
// Biplanar UDN on the original flat facet, the same coordinate / frame as the flaws.
vec3 crystal_hackle(vec3 nv, vec3 nt, vec3 vtx, vec3 tp, out float height) {
	height = 0.5;
	if (fresh < 0.5) { return nv; }
	int a;
	int b;
	float w;
	crystal_axes(nt, a, b, w);
	vec3 p = tp * hackle_scale;
	vec3 dx = dFdx(p);
	vec3 dy = dFdy(p);
	vec4 h0 = textureGrad(hackle_tex, crystal_plane(p, a), crystal_plane(dx, a), crystal_plane(dy, a));
	vec4 h1 = textureGrad(hackle_tex, crystal_plane(p, b), crystal_plane(dx, b), crystal_plane(dy, b));
	height = mix(h1.a, h0.a, w); // A is roughness, used only to vary the fresh scatter.
	vec2 t0 = h0.xy * 2.0 - 1.0;
	vec2 t1 = h1.xy * 2.0 - 1.0;
	vec3 dn = w * (crystal_axis((a + 1) % 3) * t0.x - crystal_axis((a + 2) % 3) * t0.y)
		+ (1.0 - w) * (crystal_axis((b + 1) % 3) * t1.x - crystal_axis((b + 2) % 3) * t1.y);
	dn -= nt * dot(dn, nt);
	return crystal_to_view(normalize(nt + dn * hackle_k), nv, nt, vtx, tp);
}
''';p.write_text(s)
